INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "刘仁恭经盖寓献取幽州策，求万人", "start_year": null, "end_year": null, "time_original": "刘仁恭归河东以后；数献策，起止未载", "dynasty": "唐", "description": "刘仁恭多次通过盖寓向李克用献计，愿得到一万军攻取幽州。", "phases": [], "location_name": "河东、幽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b4038a46-cd14-5c57-b33a-0022c1721784"}, {"title": "李克用围邢时分数千欲纳刘仁恭，未克", "start_year": null, "end_year": null, "time_original": "李克用攻邢州时；早于本段十一月大举，确年未定", "dynasty": "唐", "description": "李克用在攻邢州时分兵数千，想把刘仁恭送入幽州掌权，没有成功。", "phases": [], "location_name": "邢州、幽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f1c19e3c-55f0-573f-a639-9faa9cac16af"}, {"title": "李匡筹多次侵河东边境", "start_year": null, "end_year": null, "time_original": "此前多次；具体起止未载", "dynasty": "唐", "description": "李匡筹渐骄，多次侵扰河东边境。", "phases": [], "location_name": "河东边境", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "155546bf-e628-5702-8bd9-41f3cb6fc2f9"}, {"title": "李克用大举攻匡筹，取武州围新州", "start_year": 894, "end_year": 894, "time_original": "894年十一月", "dynasty": "唐", "description": "李克用因李匡筹侵境而怒，十一月大举发兵，攻取武州，进围新州。", "phases": [], "location_name": "武州、新州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c9825697-9da9-51f1-a021-9bad395658c2"}, {"title": "张鐇正式任彰义节度使", "start_year": 894, "end_year": 894, "time_original": "894年十一月条；具体日未载", "dynasty": "唐", "description": "朝廷以泾原留后张鐇为彰义节度使。", "phases": [], "location_name": "泾原、彰义", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7a29fb0d-8b8f-501e-b79c-c99dd4c652c5"}, {"title": "朱使凌慢张谏，张举泗州归杨", "start_year": 894, "end_year": 894, "time_original": "894年十一月条；具体日未载", "dynasty": "唐", "description": "朱全忠派使者到泗州，使者怠慢刺史张谏，张谏举州归降杨行密。", "phases": [], "location_name": "泗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5f2aaffe-81f3-5d97-8007-588e7f125b7b"}, {"title": "杨遣唐令回运茶贸易，朱全忠扣人夺茶", "start_year": 894, "end_year": 894, "time_original": "泗州归杨后；894年，具体日未载", "dynasty": "唐", "description": "杨行密派押牙唐令回带一万余斤茶到汴宋贸易，朱全忠扣押唐令回，尽取其茶。", "phases": [], "location_name": "汴、宋", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8890e33e-0f27-594f-a1ea-862a4dc2ed6e"}, {"title": "李匡筹数万救新州，段庄被李克用大破", "start_year": 894, "end_year": 894, "time_original": "894年十二月；具体日未载", "dynasty": "唐", "description": "李匡筹派大将率步骑数万救新州，李克用选精兵在段庄迎战，大败援军；书载斩首万余级、生擒将校三百人。", "phases": [], "location_name": "段庄、新州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d0280002-fdac-5e82-b0e4-81e203652382"}, {"title": "新州城下示俘，当夕归降", "start_year": 894, "end_year": 894, "time_original": "894年十二月；段庄战后当夕", "dynasty": "唐", "description": "李克用军把俘获将校带到城下示众，当晚新州归降。", "phases": [], "location_name": "新州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "67c75019-da7d-5895-848b-b2117aad4b38"}, {"title": "李克用进攻妫州", "start_year": 894, "end_year": 894, "time_original": "894年十二月辛亥", "dynasty": "唐", "description": "李克用军继续进攻妫州。", "phases": [], "location_name": "妫州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f3e5d2b5-1fed-5d69-9933-eea09c307215"}, {"title": "居庸关外李存审绕后夹击幽州军", "start_year": 894, "end_year": 894, "time_original": "894年十二月壬子", "dynasty": "唐", "description": "李匡筹再次发兵出居庸关；李克用用精骑正面应战使敌疲惫，并派步将李存审由另路出敌后夹击。幽州军大败，书载杀获以万计。", "phases": [], "location_name": "居庸关", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1a2d7dc1-c932-5ce2-b3dc-c34fba366573"}, {"title": "李匡筹带族奔沧州", "start_year": 894, "end_year": 894, "time_original": "894年十二月甲寅", "dynasty": "唐", "description": "李匡筹带家族逃向沧州。", "phases": [], "location_name": "幽州、沧州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "096b8ce9-4934-5cb9-ab1b-b1fbee01e889"}, {"title": "卢彦威遣军景城杀李匡筹，俘其众", "start_year": 894, "end_year": 894, "time_original": "894年十二月甲寅条；逃亡途中", "dynasty": "唐", "description": "义昌节度使卢彦威图取李匡筹的辎重与妓妾，在景城派兵攻击，杀李匡筹，俘获其部众。", "phases": [], "location_name": "景城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "403e57e0-1be1-5d9d-9fbf-1811fa20c821"}, {"title": "李克用进幽州，卢龙大将请降", "start_year": 894, "end_year": 894, "time_original": "894年十二月丙辰", "dynasty": "唐", "description": "李克用进入幽州，卢龙方面的大将请求归降。", "phases": [], "location_name": "幽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f7ad09f5-3573-5338-a85f-a5df12b46161"}, {"title": "王行约加检校待中", "start_year": 894, "end_year": 894, "time_original":