": null, "time_original": "多年政务总述；具体起止未载", "dynasty": "唐", "description": "《通鉴》称董昌为政苛虐，在常赋外加敛数倍，供贡献与内外馈赠；每旬发一纲，书载金万两、银五千鋋、越绫一万五千匹，其他物资相当。", "phases": [], "location_name": "越州、义胜", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "119b977a-3270-5c29-910d-f1cc02093f89"}, {"title": "董昌每纲五百运卒，误期遭杀", "start_year": null, "end_year": null, "time_original": "贡献运输的长期做法；起止未载", "dynasty": "唐", "description": "董昌每纲用五百运卒，遇雨雪风水延误规定时间者，书载皆死。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "af202f2f-d3a4-5ee7-956b-68ff636c7ad9"}, {"title": "朝廷以贡献为忠，累加董昌官爵", "start_year": null, "end_year": null, "time_original": "此前宠命相继；具体年月未载", "dynasty": "唐", "description": "书述董昌责奉为天下最，朝廷因而认为忠诚，多次加宠，官至司徒同平章事、爵陇西郡王。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "72e442b6-1e59-5488-94a8-6d4010a92b27"}, {"title": "董昌建越州生祠，禁止民祷禹庙", "start_year": null, "end_year": null, "time_original": "称帝谋议前的生祠做法；确年未载", "dynasty": "唐", "description": "董昌在越州建生祠，制度比照禹庙，命民间祷赛者不得去禹庙而应去生祠。", "phases": [], "location_name": "越州、禹庙、生祠", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8b1cda7c-482c-525f-ab2a-eea9cd82d0a9"}, {"title": "董昌求越王未获准，有人劝越帝", "start_year": null, "end_year": null, "time_original": "谋称帝前；具体日年未载", "dynasty": "唐", "description": "董昌请求成为越王，朝廷未准。董称自己多年贡献却得不到越王封号，认为朝廷负他；有人谄称与其为越王不如作越帝。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "293fbd22-be6b-5e5f-b7e6-964b3cd48917"}, {"title": "民间传时变请董称帝，董称待时", "start_year": 894, "end_year": 894, "time_original": "894年条的称帝筹划背景；具体日未载", "dynasty": "唐", "description": "民间讹传时世将变，人群集董昌门前喧噪请其称帝。董大喜，派人谢称天时未到，待时到自行称帝。", "phases": [], "location_name": "董昌门前", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "50a99aab-ec9b-5bef-9b27-ad62050a3c8e"}, {"title": "吴瑶李畅之等劝董昌称帝", "start_year": 894, "end_year": 894, "time_original": "894年称帝筹划时；具体日未载", "dynasty": "唐", "description": "董昌僚佐吴瑶、都虞候李畅之等劝其成就称帝计划。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "8a8dc413-be27-58e8-bd57-6e5d690bc1bf"}, {"title": "董昌赏献谣谶符瑞者，渐减赏额", "start_year": 894, "end_year": 894, "time_original": "894年称帝筹划时；先后确日未载", "dynasty": "唐", "description": "吏民献谣谶符瑞者很多，董昌最初赏数百缗，献者日增后逐渐减到五百、三百。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "dd3ac3cb-2165-5eea-aae6-311750dfb368"}, {"title": "董昌解释兔子谶，预告明年卯日称帝", "start_year": 894, "end_year": 894, "time_original": "894年；声称将在明年二月卯日卯时称帝", "dynasty": "唐", "description": "董昌说兔子上金床的谶指自己，称自己生于卯岁、明年又逢卯年，计划在明年二月卯日卯时称帝。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "76a46345-c21f-5fe8-bf0b-ce00d223f483"}]'::jsonb)
