SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "刘仁恭多次通过盖寓向李克用献计，愿得到一万军攻取幽州。", "citation": "卷259·乾宁元年（894）·zztj-v259-y0894-p025·原文件第118行", "note": "原文：刘仁恭数因盖寓献策于李克用，愿得兵万人取幽州。；核对说明：愿得是请求，非实际获授万人；数次起止不详，不因在十一月条就把早先献策全记十一月。", "status": "draft", "id": "fc05068b-3985-55b7-a8db-ea7e5030da5c", "subject_id": "b4038a46-cd14-5c57-b33a-0022c1721784", "source_id": "ee2a8086-0e0a-5257-8fa6-23127b09f219"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "刘仁恭归河东以后；数献策，起止未载", "citation": "卷259·乾宁元年（894）·zztj-v259-y0894-p025·原文件第118行", "note": "原文：刘仁恭数因盖寓献策于李克用，愿得兵万人取幽州。；核对说明：愿得是请求，非实际获授万人；数次起止不详，不因在十一月条就把早先献策全记十一月。", "status": "draft", "id": "1636ec99-1b51-5f98-b675-4c1da175d0a3", "subject_id": "b4038a46-cd14-5c57-b33a-0022c1721784", "source_id": "ee2a8086-0e0a-5257-8fa6-23127b09f219"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记刘仁恭：献策求兵者。", "citation": "卷259·乾宁元年（894）·zztj-v259-y0894-p025·原文件第118行", "note": "原文：刘仁恭数因盖寓献策于李克用，愿得兵万人取幽州。克用方攻邢州，分兵数千，欲纳仁恭于幽州，不克。李匡筹益骄，数侵河东之境。克用怒，十一月，大举兵攻匡筹，拨武州，进围新州。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "725f8f79-879d-5a47-9c96-9a9784de4e3e", "subject_id": "b8f07571-c891-57ce-b69c-3e4a58148227", "source_id": "ee2a8086-0e0a-5257-8fa6-23127b09f219"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "刘仁恭：献策求兵者。", "citation": "卷259·乾宁元年（894）·zztj-v259-y0894-p025·原文件第118行", "note": "原文：刘仁恭数因盖寓献策于李克用，愿得兵万人取幽州。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "0708c2ff-0050-562b-bfcf-9e49335b7667", "subject_id": "fc6b691a-5da3-5325-a94a-050a67909f8b", "source_id": "ee2a8086-0e0a-5257-8fa6-23127b09f219"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记盖寓：转呈献策中介。", "citation": "卷259·乾宁元年（894）·zztj-v259-y0894-p025·原文件第118行", "note": "原文：刘仁恭数因盖寓献策于李克用，愿得兵万人